<script setup lang="ts">
import { computed, ref } from 'vue'
import { FileText, FileImage, Link2, Plus, Download, Pencil, FolderArchive } from 'lucide-vue-next'
import { MATERIAL_KINDS, type ProjectMaterial } from '../../shared/domain'
const props=defineProps<{materials:ProjectMaterial[];busy:boolean}>()
const emit=defineEmits<{add:[];edit:[material:ProjectMaterial];download:[material:ProjectMaterial]}>()
const filter=ref('전체')
const visible=computed(()=>[...props.materials].filter(material=>filter.value==='전체'||material.kind===filter.value).sort((a,b)=>b.updated_at.localeCompare(a.updated_at)))
</script>
<template>
  <section class="project-archive" aria-label="프로젝트 자료 보관함">
    <div class="archive-heading"><div><h2>자료 보관함 <span class="count-pill">{{ materials.length }}</span></h2><p>자소서·포트폴리오·JD·기업 분석을 이 프로젝트에 모아두세요.</p></div><button class="primary-button" @click="emit('add')"><Plus :size="17" />자료 추가</button></div>
    <div class="archive-filters" role="group" aria-label="자료 분류"><button v-for="kind in ['전체',...MATERIAL_KINDS]" :key="kind" :aria-pressed="filter===kind" @click="filter=kind">{{ kind }}</button></div>
    <div v-if="visible.length" class="archive-grid"><article v-for="material in visible" :key="material.id" class="archive-card"><div class="archive-card-top"><span class="archive-file-icon"><FileImage v-if="material.file_type?.startsWith('image/')" :size="24" /><FileText v-else :size="24" /></span><span class="archive-kind">{{ material.kind }}</span><button class="icon-button" aria-label="자료 수정" @click="emit('edit',material)"><Pencil :size="16" /></button></div><button class="archive-title" @click="emit('edit',material)">{{ material.title }}</button><p v-if="material.content" class="archive-preview">{{ material.content }}</p><div v-if="material.file_name" class="archive-attachment"><FileText :size="15" /><span>{{ material.file_name }}</span><small>{{ ((material.file_size||0)/1024/1024).toFixed(1) }} MB</small></div><div class="archive-actions"><button v-if="material.storage_path" :disabled="busy" @click="emit('download',material)"><Download :size="15" />파일 받기</button><a v-if="material.url" :href="material.url" target="_blank" rel="noopener noreferrer"><Link2 :size="15" />링크 열기</a><span>{{ material.updated_at.slice(0,10).replaceAll('-','.') }}</span></div></article></div>
    <div v-else class="empty-state"><div class="empty-icon"><FolderArchive :size="30" /></div><h3>{{ materials.length?'이 분류에 등록한 자료가 없어요':'준비 자료를 한곳에 보관하세요' }}</h3><p>텍스트와 링크, PDF·문서·이미지 파일을 저장할 수 있습니다.</p><button class="outline-button" @click="emit('add')"><Plus :size="16" />자료 추가</button></div>
  </section>
</template>
